  let p = vec2f(uv.x * aspect, uv.y);
  let t = params.time;

  let cells = vec2f(9.0 * max(aspect, 1.0), 9.0);
  let id = floor(p * cells);
  let h = hash2(id);
  let h2 = hash2(id + 31.7);
  let h3 = hash2(id + 57.3);

